-- ════════════════════════════════════════════════════════
-- 213 — Lot 4c du second recensement : les isolees de quatre pays
-- ────────────────────────────────────────────────────────
-- Sept maisons sans usine, rangees par le pays ou elles sont roulees :
--   NICARAGUA    Fable Cigars (Nica Sueno, puis Cordoba & Morales depuis oct. 2025)
--   HONDURAS     Jake Wyatt Cigar Co. (Tabacalera San Jeronimo, Danli, depuis 2026)
--   DOMINICAINE  Hiram & Solomon (PDR), Epic (von Eicken), Chogui (Rivas),
--                Principle (KBF)
--   COSTA RICA   Bombay Tobak / MBombay (Tabacos de Costa Rica, Puriscal)
--
-- DEUX MAISONS REPORTEES, chacune pour une raison ecrite :
--   Jas Sum Kral — a quitte Tabacalera Aragon le 11 octobre 2024 et n'a
--     jamais nomme sa nouvelle fabrique. Sans fabrique nommee, pas de fiche.
--   Casa 1910 — la presse du metier ecrit en mars 2026 que la maison ne
--     divulgue pas quelle fabrique mexicaine roule ses cigares ; les deux
--     lignes faites ailleurs (Soldadera a La Isla, Cavalry) sont arretees.
--     Meme regle.
--
-- Deux divergences ecrites au lieu d'etre tranchees :
--   Jake Wyatt disait posseder une fabrique, Casamorabo ; la presse etablit
--     en 2026 que tout part chez San Jeronimo apres des ateliers dominicains.
--     La fiche attribue l'affirmation a la maison et classe au Honduras.
--   Principle : le recensement disait ~2011, la devise de la maison dit 2013.
--
-- Renvois rendus reciproques : PDR -> Hiram & Solomon, KBF -> Principle,
-- Kristoff -> Epic (meme fabrique), De Los Reyes -> Chogui (tabacs de Leo
-- Reyes), Warped -> Chogui (Venture 1492), RoMa Craft -> Fable (Nica Sueno).
-- La fiche Vegas de Santiago recoit un paragraphe : MBombay est la
-- troisieme marque de l'atlas roulee a Puriscal.
--
-- `producer_countries.brands` lu dans la base et reecrit en litteral.
-- Domaines verifies au DNS avant ecriture : halfwheel.com, cigar-coop.com,
-- fablecigars.com, cigarlifeguy.com, jakewyattcigars.com, cigarsnobmag.com,
-- epiccigars.com, smallbatchcigar.com, principletrading.com, wina-mp.pl,
-- cigaraficionado.com.
-- ════════════════════════════════════════════════════════

-- ── Fable Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Fable Cigars',
        'nicaragua',
        '2016 — chez Córdoba & Morales',
        'Sans usine — Fábrica de Tabacos Nica Sueño (RoMa Craft) jusqu''à l''éclipse, Córdoba & Morales, Estelí, depuis octobre 2025',
        'halfwheel.com « Fable Returns to Market, Moves Production to Córdoba & Morales » (16 octobre 2025 : lancée en 2016 par Sean Kremenetski et Mitul Shah, absente du marché près de la moitié du temps depuis ; Fourth Prime passe de Nica Sueño à Córdoba & Morales, même assemblage sur le papier — cape broadleaf de Pennsylvanie, sous-cape Habano ligero d''Équateur, tripes dominicaine et nicaraguayenne ; sept vitoles avant, quatre au retour ; boîtes de 56 devenues 21 ; distributeur Pospiech) ; cigar-coop.com « Fable Cigars Announces Relaunch » (la maison explique sur son site que Fourth Prime raconte le nombre 7, quatrième nombre premier, et que le triangle du logo en est fait de sept traits) ; fablecigars.com',
        'Fable est une maison de 2016, fondée par Sean Kremenetski et Mitul Shah, un détaillant, et son histoire tient en une éclipse : elle a été absente du marché à peu près la moitié du temps depuis sa naissance, et elle est revenue en octobre 2025. L''atlas l''écrit au retour, pas au départ.

Sa seule ligne, Fourth Prime, raconte le nombre 7 — le quatrième nombre premier — et la maison explique que ses formats en portent le nom et que le triangle de son logo est fait de sept traits. Les premiers cigares sortaient de la Fábrica de Tabacos Nica Sueño, l''atelier de RoMa Craft à Estelí, dont l''atlas porte la fiche. Au retour, la production est passée chez Córdoba & Morales, à Estelí également, une fabrique que cet atlas nomme ici et n''a pas encore décrite. L''assemblage est donné pour le même : cape broadleaf de Pennsylvanie, sous-cape Habano ligero d''Équateur, tripes dominicaine et nicaraguayenne.

Ce qui a changé se compte : sept vitoles avant l''éclipse, quatre au retour ; des boîtes de cinquante-six devenues des boîtes de vingt et un ; des prix montés. Une maison qui revient avec la même recette et une autre fabrique — c''est exactement le cas que la règle de l''atlas est faite pour écrire : le pays est celui où le cigare est roulé aujourd''hui, et la fabrique est nommée.',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"Broadleaf de Pennsylvanie","vitolas":[],"story":"Le nombre 7 — quatrième nombre premier. Sept vitoles avant l''éclipse, quatre au retour d''octobre 2025 : Mersenne, Sapta, Friday, Machu."}]',
        'Fable is a house of 2016, founded by Sean Kremenetski and Mitul Shah, a retailer, and its story fits in an eclipse: it has been absent from the market about half the time since its birth, and it came back in October 2025. This atlas writes it at the return, not at the start.

Its only line, Fourth Prime, tells the number 7 — the fourth prime number — and the house explains that its sizes carry its name and that the triangle of its logo is made of seven strokes. The first cigars came out of Fábrica de Tabacos Nica Sueño, RoMa Craft''s workshop in Estelí, whose entry this atlas carries. At the return, production moved to Córdoba & Morales, also in Estelí, a factory this atlas names here and has not yet described. The blend is given as the same: Pennsylvania broadleaf wrapper, Ecuadorian Habano ligero binder, Dominican and Nicaraguan fillers.

What changed can be counted: seven vitolas before the eclipse, four at the return; boxes of fifty-six become boxes of twenty-one; prices up. A house that returns with the same recipe and another factory — this is exactly the case the atlas''s rule is made to write: the country is where the cigar is rolled today, and the factory is named.',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"Pennsylvania broadleaf","vitolas":[],"story":"The number 7 — the fourth prime. Seven vitolas before the eclipse, four at the October 2025 return: Mersenne, Sapta, Friday, Machu."}]',
        'Fable es una casa de 2016, fundada por Sean Kremenetski y Mitul Shah, un minorista, y su historia cabe en un eclipse: ha estado ausente del mercado cerca de la mitad del tiempo desde su nacimiento, y volvió en octubre de 2025. Este atlas la escribe al regreso, no a la salida.

Su única línea, Fourth Prime, cuenta el número 7 — el cuarto número primo — y la casa explica que sus formatos llevan su nombre y que el triángulo de su logotipo está hecho de siete trazos. Los primeros puros salían de la Fábrica de Tabacos Nica Sueño, el taller de RoMa Craft en Estelí, cuya ficha lleva este atlas. Al regreso, la producción pasó a Córdoba & Morales, también en Estelí, una fábrica que este atlas nombra aquí y aún no ha descrito. La ligada se da por la misma: capa broadleaf de Pensilvania, capote Habano ligero de Ecuador, tripas dominicana y nicaragüense.

Lo que cambió se cuenta: siete vitolas antes del eclipse, cuatro al regreso; cajas de cincuenta y seis convertidas en cajas de veintiuno; precios subidos. Una casa que vuelve con la misma receta y otra fábrica — es exactamente el caso para el que está hecha la regla del atlas: el país es donde se lía el puro hoy, y la fábrica se nombra.',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"Broadleaf de Pensilvania","vitolas":[],"story":"El número 7 — cuarto número primo. Siete vitolas antes del eclipse, cuatro al regreso de octubre de 2025: Mersenne, Sapta, Friday, Machu."}]',
        'Fable ist ein Haus von 2016, gegründet von Sean Kremenetski und Mitul Shah, einem Händler, und seine Geschichte passt in eine Finsternis: Es war seit seiner Geburt etwa die Hälfte der Zeit vom Markt verschwunden, und es kam im Oktober 2025 zurück. Dieser Atlas schreibt es bei der Rückkehr, nicht beim Start.

Seine einzige Linie, Fourth Prime, erzählt die Zahl 7 — die vierte Primzahl —, und das Haus erklärt, dass seine Formate ihren Namen tragen und dass das Dreieck seines Logos aus sieben Strichen besteht. Die ersten Zigarren kamen aus der Fábrica de Tabacos Nica Sueño, der Werkstatt von RoMa Craft in Estelí, deren Eintrag dieser Atlas führt. Bei der Rückkehr wechselte die Produktion zu Córdoba & Morales, ebenfalls in Estelí, einer Fabrik, die dieser Atlas hier nennt und noch nicht beschrieben hat. Der Blend gilt als derselbe: Pennsylvania-Broadleaf-Deckblatt, ecuadorianisches Habano-Ligero-Umblatt, dominikanische und nicaraguanische Einlage.

Was sich änderte, lässt sich zählen: sieben Vitolas vor der Finsternis, vier bei der Rückkehr; Kisten zu sechsundfünfzig wurden Kisten zu einundzwanzig; die Preise stiegen. Ein Haus, das mit demselben Rezept und einer anderen Fabrik zurückkehrt — genau dafür ist die Regel des Atlas gemacht: Das Land ist, wo die Zigarre heute gerollt wird, und die Fabrik wird genannt.',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"Pennsylvania-Broadleaf","vitolas":[],"story":"Die Zahl 7 — die vierte Primzahl. Sieben Vitolas vor der Finsternis, vier bei der Rückkehr im Oktober 2025: Mersenne, Sapta, Friday, Machu."}]',
        'Fable 是2016年的公司，由肖恩·克雷梅涅茨基与零售商米图尔·沙阿创办，它的故事可以装进一次日食：自诞生以来约有一半时间缺席市场，2025年10月回归。本图集在回归时写它，而非出发时。

它唯一的系列 Fourth Prime 讲述数字7——第四个质数——公司解释说各尺寸以此命名，标志上的三角形由七道线条构成。早期雪茄出自埃斯特利 RoMa Craft 的作坊 Fábrica de Tabacos Nica Sueño，本图集载有其词条。回归后，生产转到同在埃斯特利的 Córdoba & Morales，本图集在此点名而尚未描述的一家工厂。配方据称不变：宾夕法尼亚 broadleaf 茄衣、厄瓜多尔 Habano ligero 茄套、多米尼加与尼加拉瓜填充。

变化可以数出来：日食前七种尺寸，回归后四种；五十六支装变为二十一支装；价格上调。一家带着同样配方与另一家工厂回归的公司——正是本图集的规则为之而设的情形：国家是雪茄今日卷制之地，工厂被点名。',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"宾夕法尼亚 broadleaf","vitolas":[],"story":"数字7——第四个质数。日食前七种尺寸，2025年10月回归后四种：Mersenne、Sapta、Friday、Machu。"}]',
        'فابل دارٌ من 2016، أسّسها شون كريمينيتسكي وميتول شاه، وهو تاجر تجزئة، وقصّتها تتّسع لها كسوفٌ واحد: غابت عن السوق نحو نصف الوقت منذ ولادتها، وعادت في تشرين الأوّل/أكتوبر 2025. يكتبها هذا الأطلس عند العودة لا عند الانطلاق.

خطّها الوحيد، Fourth Prime، يروي الرقم 7 — العدد الأوّلي الرابع — وتشرح الدار أنّ قياساتها تحمل اسمه وأنّ مثلّث شعارها مصنوع من سبعة خطوط. خرجت السيجارات الأولى من Fábrica de Tabacos Nica Sueño، ورشة RoMa Craft في إستيلي التي يحمل هذا الأطلس بطاقتها. وعند العودة انتقل الإنتاج إلى Córdoba & Morales، في إستيلي أيضًا، مصنعٌ يسمّيه هذا الأطلس هنا ولم يصفه بعد. وتُعطى المزجة على أنّها نفسها: غلاف برودليف من بنسلفانيا، ورقة رابطة هابانو ليخيرو إكوادورية، حشوة دومينيكية ونيكاراغوية.

ما تغيّر يُعدّ: سبع فيتولات قبل الكسوف، وأربع عند العودة؛ علب الستّ والخمسين صارت علب الواحد والعشرين؛ والأسعار ارتفعت. دارٌ تعود بالوصفة نفسها ومصنع آخر — هذه بالضبط الحالة التي صُنعت قاعدة الأطلس لكتابتها: البلد هو حيث يُلفّ السيجار اليوم، والمصنع يُسمّى.',
        '[{"name":"Fourth Prime","color":"#3A3A3A","force":"Medium-Full","wrapper":"برودليف من بنسلفانيا","vitolas":[],"story":"الرقم 7 — العدد الأوّلي الرابع. سبع فيتولات قبل الكسوف، وأربع عند عودة تشرين الأوّل/أكتوبر 2025: Mersenne وSapta وFriday وMachu."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Jake Wyatt Cigar Co. ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Jake Wyatt Cigar Co.',
        'honduras',
        'Février 2020 — chez San Jerónimo, Danlí',
        'Sans usine — Tabacalera San Jerónimo, Danlí, depuis 2026 ; ateliers dominicains auparavant',
        'halfwheel.com « Jake Wyatt Cigar Co. Releases Value-Focused Titan Series » (1er avril 2026 : lancée en février 2020 par Neil Garcia et Gerard Abajian, le nom vient des prénoms de leurs fils ; toute la production vient d''être transférée à la Tabacalera San Jerónimo de Danlí après une poignée de fabriques dominicaines ; Neil Garcia, président, dit que la gamme entière a été refaite sur des tabacs honduriens et nicaraguayens ; série Titan — Goliad, Colossus, Omega — boîtes de 22) ; cigarlifeguy.com « Jake Wyatt Cigars: Interview with Gerard Abajian » (Abajian, dix ans pompier, fils d''un détaillant californien ; la maison disait alors posséder une fabrique de 20 000 pieds carrés nommée Casamorabo ; la boîte de 22 vient du numéro de maillot de Garcia au baseball) ; jakewyattcigars.com',
        'Jake Wyatt porte deux prénoms d''enfants : Jake, le fils de Neil Garcia, et Wyatt, celui de Gerard Abajian. Les deux associés ont lancé la maison en février 2020 — Abajian après dix ans de service comme pompier et une jeunesse derrière le comptoir de la boutique de son père, en Californie ; Garcia après le baseball, et la boîte de vingt-deux cigares est son numéro de maillot.

La maison a commencé en République dominicaine, où les deux hommes ont fait le tour des fabriques qui leur proposaient des échantillons. Elle a dit ensuite posséder son propre atelier, une entité séparée nommée Casamorabo, de vingt mille pieds carrés ; l''atlas rapporte cette affirmation à la maison sans avoir pu la vérifier ailleurs. Ce qui est établi par la presse du métier, en avril 2026, c''est l''inverse : toute la production vient d''être transférée à la Tabacalera San Jerónimo, à Danlí, au Honduras, après une poignée de fabriques dominicaines, et la gamme entière a été refaite sur des tabacs honduriens et nicaraguayens. La fiche est donc hondurienne, par la règle du lieu de roulage.

Le catalogue se lit en collections — Gourmet, aux bagues ouvragées faites pour la photographie, et Connoisseur, plus sobre — auxquelles la série Titan a ajouté, en 2026, trois cigares de tous les jours : Goliad, Colossus, Omega.',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Une ligne de la collection Connoisseur, offerte aussi en figurado."},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Goliad, Colossus, Omega — trois cigares de tous les jours, 2026, sous-cape et tripes du Honduras et du Nicaragua."}]',
        'Jake Wyatt carries two children''s first names: Jake, Neil Garcia''s son, and Wyatt, Gerard Abajian''s. The two partners launched the house in February 2020 — Abajian after ten years as a firefighter and a youth behind the counter of his father''s shop in California; Garcia after baseball, and the box of twenty-two cigars is his jersey number.

The house began in the Dominican Republic, where the two men toured the factories that offered them samples. It later said it owned its own workshop, a separate entity named Casamorabo, of twenty thousand square feet; this atlas attributes that statement to the house without having been able to verify it elsewhere. What the trade press establishes, in April 2026, is the reverse: all production has just been moved to Tabacalera San Jerónimo, in Danlí, Honduras, after a handful of Dominican factories, and the entire range has been remade on Honduran and Nicaraguan tobaccos. The entry is therefore Honduran, by the rule of the rolling place.

The catalogue reads in collections — Gourmet, with worked bands made for photography, and Connoisseur, plainer — to which the Titan series added, in 2026, three everyday cigars: Goliad, Colossus, Omega.',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"A line of the Connoisseur collection, also offered as a figurado."},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Goliad, Colossus, Omega — three everyday cigars, 2026, Honduran binder, Honduran and Nicaraguan fillers."}]',
        'Jake Wyatt lleva dos nombres de niños: Jake, el hijo de Neil Garcia, y Wyatt, el de Gerard Abajian. Los dos socios lanzaron la casa en febrero de 2020 — Abajian tras diez años de bombero y una juventud detrás del mostrador de la tienda de su padre, en California; Garcia tras el béisbol, y la caja de veintidós puros es su número de camiseta.

La casa empezó en la República Dominicana, donde los dos hombres recorrieron las fábricas que les ofrecían muestras. Dijo después poseer su propio taller, una entidad separada llamada Casamorabo, de veinte mil pies cuadrados; este atlas atribuye esa afirmación a la casa sin haber podido verificarla en otra parte. Lo que la prensa del oficio establece, en abril de 2026, es lo contrario: toda la producción acaba de trasladarse a la Tabacalera San Jerónimo, en Danlí, Honduras, tras un puñado de fábricas dominicanas, y la gama entera se rehízo con tabacos hondureños y nicaragüenses. La ficha es pues hondureña, por la regla del lugar de liado.

El catálogo se lee en colecciones — Gourmet, con anillas trabajadas hechas para la fotografía, y Connoisseur, más sobria — a las que la serie Titan añadió, en 2026, tres puros de cada día: Goliad, Colossus, Omega.',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Una línea de la colección Connoisseur, ofrecida también en figurado."},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Goliad, Colossus, Omega — tres puros de cada día, 2026, capote hondureño, tripas de Honduras y Nicaragua."}]',
        'Jake Wyatt trägt zwei Kindervornamen: Jake, den Sohn von Neil Garcia, und Wyatt, den von Gerard Abajian. Die beiden Partner lancierten das Haus im Februar 2020 — Abajian nach zehn Jahren als Feuerwehrmann und einer Jugend hinter dem Tresen des Ladens seines Vaters in Kalifornien; Garcia nach dem Baseball, und die Kiste mit zweiundzwanzig Zigarren ist seine Trikotnummer.

Das Haus begann in der Dominikanischen Republik, wo die beiden Männer die Fabriken abklapperten, die ihnen Muster anboten. Später sagte es, eine eigene Werkstatt zu besitzen, eine getrennte Einheit namens Casamorabo, zwanzigtausend Quadratfuß groß; dieser Atlas schreibt diese Aussage dem Haus zu, ohne sie anderswo bestätigen zu können. Was die Fachpresse im April 2026 feststellt, ist das Gegenteil: Die gesamte Produktion wurde gerade zur Tabacalera San Jerónimo in Danlí, Honduras, verlegt, nach einer Handvoll dominikanischer Fabriken, und das gesamte Sortiment wurde auf honduranischen und nicaraguanischen Tabaken neu gemacht. Der Eintrag ist daher honduranisch, nach der Regel des Rollorts.

Der Katalog liest sich in Kollektionen — Gourmet, mit gearbeiteten Bauchbinden für die Fotografie, und Connoisseur, schlichter —, denen die Titan-Serie 2026 drei Alltagszigarren hinzufügte: Goliad, Colossus, Omega.',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Eine Linie der Connoisseur-Kollektion, auch als Figurado angeboten."},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Goliad, Colossus, Omega — drei Alltagszigarren, 2026, honduranisches Umblatt, Einlage aus Honduras und Nicaragua."}]',
        'Jake Wyatt 由两个孩子的名字组成：尼尔·加西亚的儿子杰克，与杰拉德·阿巴吉安的儿子怀亚特。两位合伙人2020年2月创办公司——阿巴吉安当了十年消防员，少年时在父亲加州的店里站柜台；加西亚打过棒球，二十二支装的盒数就是他的球衣号码。

公司从多米尼加共和国起步，两人走访了给他们提供样品的工厂。后来它自称拥有一家独立的自有作坊，名为 Casamorabo，两万平方英尺；本图集把这一说法归于公司本身，未能在别处核实。行业媒体在2026年4月确认的却相反：全部生产刚刚转到洪都拉斯丹利的 Tabacalera San Jerónimo，此前经过了几家多米尼加工厂，且整个系列已用洪都拉斯与尼加拉瓜烟叶重新调配。因此按卷制地规则，词条归入洪都拉斯。

目录按系列阅读——Gourmet，茄标精工、为拍照而生；Connoisseur，更为朴素——2026年 Titan 系列又添了三支日常雪茄：Goliad、Colossus、Omega。',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"Connoisseur 系列中的一条线，也有 figurado 版本。"},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"未公开","vitolas":[],"story":"Goliad、Colossus、Omega——三支日常雪茄，2026年，洪都拉斯茄套，洪都拉斯与尼加拉瓜填充。"}]',
        'يحمل جيك وايت اسمَي طفلين: جيك، ابن نيل غارسيا، ووايت، ابن جيرارد أباجيان. أطلق الشريكان الدار في شباط/فبراير 2020 — أباجيان بعد عشر سنوات إطفائيًّا وشبابٍ خلف طاولة متجر أبيه في كاليفورنيا؛ وغارسيا بعد البيسبول، وعلبة الاثنين والعشرين سيجارًا هي رقم قميصه.

بدأت الدار في جمهورية الدومينيكان، حيث طاف الرجلان على المصانع التي عرضت عليهما عيّنات. ثم قالت إنّها تملك ورشتها الخاصة، كيانًا منفصلًا اسمه Casamorabo بمساحة عشرين ألف قدم مربّع؛ ينسب هذا الأطلس ذلك القول إلى الدار من دون أن يتمكّن من التحقّق منه في مكان آخر. أمّا ما تثبته صحافة المهنة في نيسان/أبريل 2026 فهو العكس: نُقل الإنتاج كلّه للتوّ إلى Tabacalera San Jerónimo في دانلي بهندوراس، بعد حفنة من المصانع الدومينيكية، وأُعيدت صياغة التشكيلة كلّها على أتبغة هندوراسية ونيكاراغوية. فالبطاقة إذن هندوراسية، بقاعدة مكان اللفّ.

يُقرأ الكتالوج مجموعاتٍ — Gourmet بأحزمة مشغولة صُنعت للتصوير، وConnoisseur الأكثر رصانة — أضافت إليها سلسلة Titan سنة 2026 ثلاث سيجارات يومية: Goliad وColossus وOmega.',
        '[{"name":"Appendix II","color":"#4A3728","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"خطّ من مجموعة Connoisseur، يُقدَّم أيضًا بشكل figurado."},{"name":"Titan Series","color":"#6B4226","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"Goliad وColossus وOmega — ثلاث سيجارات يومية، 2026، ورقة رابطة هندوراسية وحشوة من هندوراس ونيكاراغوا."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Hiram & Solomon ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Hiram & Solomon',
        'dominican',
        '2015 — Fouad Kashouty et George Dakrat ; chez PDR',
        'Sans usine — PDR Cigars (Abe Flores), Tamboril, depuis juin 2022 ; ateliers dominicains, puis Plasencia, auparavant',
        'halfwheel.com « Hiram & Solomon Moving All Production to PDR Cigars » (18 juin 2022 : fin de l''accord de fulfillment avec Blanco Cigars deux semaines plus tôt ; tout le portefeuille passe chez PDR, à Tamboril — Entered Apprentice, Fellow Craft, Master Mason, Veiled Prophet, Traveling Man, Shriner, Grand Architect, 300th Anniversary, Unity ; Fouad et Romy Kashouty travaillent avec Abe Flores depuis 2021 ; Curamus, février 2021, Châbal, Revival et Sublime Prince 32, 2022, déjà chez PDR ; Abe Flores dit à la presse qu''ils ont voulu travailler avec lui seul) ; cigar-coop.com « IPCPR 2019 Spotlight: Hiram & Solomon » (fondée en 2015 par Fouad Kashouty et George Dakrat ; production d''abord en Rép. dominicaine, puis chez Plasencia ; tabac paraguayen dans Entered Apprentice et Veiled Prophet) ; cigarsnobmag.com',
        'Hiram & Solomon est une marque écrite pour les francs-maçons, par des francs-maçons : Hiram Abiff, l''architecte légendaire du Temple, et Salomon, le roi qui le fit bâtir. Fouad Kashouty et George Dakrat l''ont fondée en 2015, et les lignes s''appellent comme les degrés et les offices de la loge — Entered Apprentice, Fellow Craft, Master Mason, Grand Architect, Shriner, Veiled Prophet, Traveling Man. L''idée, dit la maison, est que des frères puissent se retrouver autour d''un cigare. La fiche n''a pas à juger l''idée ; elle note qu''elle est tenue depuis dix ans.

Ce que l''atlas doit établir, c''est qui roule. La maison a commencé en République dominicaine, puis a confié une grande part de sa production à Plasencia. En 2021, Fouad et Romy Kashouty ont commencé à composer avec Abe Flores, le maître assembleur de PDR Cigars, à Tamboril — Curamus en février 2021, puis Châbal, Revival et Sublime Prince 32 au début de 2022. En juin 2022, deux semaines après la fin de son accord de fulfillment avec Blanco Cigars, la maison a annoncé que tout son portefeuille passait chez PDR. Flores a dit à la presse du métier qu''ils avaient voulu travailler avec lui seul, sans autre fabrique.

La fiche PDR de cet atlas le nomme déjà ; celle-ci ferme la boucle. Entered Apprentice et Veiled Prophet ont une particularité que peu de fiches peuvent écrire : du tabac paraguayen dans l''assemblage.',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Le degré de maître — la ligne de tête, roulée chez PDR depuis 2022."},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''apprenti entré — du tabac paraguayen dans l''assemblage."},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Février 2021 — le premier cigare composé avec Abe Flores."}]',
        'Hiram & Solomon is a brand written for Freemasons, by Freemasons: Hiram Abiff, the legendary architect of the Temple, and Solomon, the king who had it built. Fouad Kashouty and George Dakrat founded it in 2015, and the lines are named like the degrees and offices of the lodge — Entered Apprentice, Fellow Craft, Master Mason, Grand Architect, Shriner, Veiled Prophet, Traveling Man. The idea, the house says, is that brothers can gather around a cigar. The entry has no opinion on the idea; it notes that it has been kept for ten years.

What this atlas must establish is who rolls. The house began in the Dominican Republic, then entrusted a large share of its production to Plasencia. In 2021, Fouad and Romy Kashouty began composing with Abe Flores, the master blender of PDR Cigars, in Tamboril — Curamus in February 2021, then Châbal, Revival and Sublime Prince 32 in early 2022. In June 2022, two weeks after the end of its fulfillment agreement with Blanco Cigars, the house announced that its entire portfolio was moving to PDR. Flores told the trade press that they had wanted to work with him alone, with no other factory.

This atlas''s PDR entry already names it; this one closes the loop. Entered Apprentice and Veiled Prophet have a particularity few entries can write: Paraguayan tobacco in the blend.',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The master degree — the lead line, rolled at PDR since 2022."},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The entered apprentice — Paraguayan tobacco in the blend."},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"February 2021 — the first cigar composed with Abe Flores."}]',
        'Hiram & Solomon es una marca escrita para masones, por masones: Hiram Abiff, el arquitecto legendario del Templo, y Salomón, el rey que lo hizo construir. Fouad Kashouty y George Dakrat la fundaron en 2015, y las líneas se llaman como los grados y oficios de la logia — Entered Apprentice, Fellow Craft, Master Mason, Grand Architect, Shriner, Veiled Prophet, Traveling Man. La idea, dice la casa, es que los hermanos puedan reunirse en torno a un puro. La ficha no juzga la idea; anota que se mantiene desde hace diez años.

Lo que este atlas debe establecer es quién lía. La casa empezó en la República Dominicana, luego confió gran parte de su producción a Plasencia. En 2021, Fouad y Romy Kashouty empezaron a componer con Abe Flores, el maestro ligador de PDR Cigars, en Tamboril — Curamus en febrero de 2021, luego Châbal, Revival y Sublime Prince 32 a principios de 2022. En junio de 2022, dos semanas después del fin de su acuerdo de fulfillment con Blanco Cigars, la casa anunció que todo su portafolio pasaba a PDR. Flores dijo a la prensa del oficio que habían querido trabajar con él solo, sin otra fábrica.

La ficha PDR de este atlas ya la nombra; esta cierra el círculo. Entered Apprentice y Veiled Prophet tienen una particularidad que pocas fichas pueden escribir: tabaco paraguayo en la ligada.',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El grado de maestro — la línea principal, liada en PDR desde 2022."},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El aprendiz — tabaco paraguayo en la ligada."},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Febrero de 2021 — el primer puro compuesto con Abe Flores."}]',
        'Hiram & Solomon ist eine Marke, geschrieben für Freimaurer, von Freimaurern: Hiram Abiff, der legendäre Baumeister des Tempels, und Salomo, der König, der ihn bauen ließ. Fouad Kashouty und George Dakrat gründeten sie 2015, und die Linien heißen wie die Grade und Ämter der Loge — Entered Apprentice, Fellow Craft, Master Mason, Grand Architect, Shriner, Veiled Prophet, Traveling Man. Die Idee, sagt das Haus, ist, dass Brüder sich um eine Zigarre versammeln können. Der Eintrag urteilt nicht über die Idee; er vermerkt, dass sie seit zehn Jahren gehalten wird.

Was dieser Atlas feststellen muss, ist, wer rollt. Das Haus begann in der Dominikanischen Republik, dann vertraute es einen großen Teil seiner Produktion Plasencia an. 2021 begannen Fouad und Romy Kashouty, mit Abe Flores zu komponieren, dem Master Blender von PDR Cigars in Tamboril — Curamus im Februar 2021, dann Châbal, Revival und Sublime Prince 32 Anfang 2022. Im Juni 2022, zwei Wochen nach dem Ende seiner Fulfillment-Vereinbarung mit Blanco Cigars, kündigte das Haus an, dass sein gesamtes Portfolio zu PDR wechselt. Flores sagte der Fachpresse, sie hätten mit ihm allein arbeiten wollen, ohne andere Fabrik.

Der PDR-Eintrag dieses Atlas nennt sie bereits; dieser schließt den Kreis. Entered Apprentice und Veiled Prophet haben eine Besonderheit, die wenige Einträge schreiben können: paraguayischen Tabak im Blend.',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Meistergrad — die Hauptlinie, seit 2022 bei PDR gerollt."},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Lehrling — paraguayischer Tabak im Blend."},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Februar 2021 — die erste mit Abe Flores komponierte Zigarre."}]',
        'Hiram & Solomon 是共济会员为共济会员而写的品牌：希兰·阿比夫，传说中圣殿的建筑师；所罗门，下令建造圣殿的国王。富阿德·卡舒蒂与乔治·达克拉特2015年创办，各系列以会所的等级与职务命名——Entered Apprentice、Fellow Craft、Master Mason、Grand Architect、Shriner、Veiled Prophet、Traveling Man。公司说，用意是让弟兄们围着一支雪茄相聚。词条不评判这个想法；只记下它已坚持十年。

本图集要确定的是谁在卷。公司从多米尼加共和国起步，后来把大部分生产托付给 Plasencia。2021年，富阿德与罗米·卡舒蒂开始与坦博里尔 PDR Cigars 的调配大师阿贝·弗洛雷斯合作调配——2021年2月的 Curamus，随后是2022年初的 Châbal、Revival 与 Sublime Prince 32。2022年6月，在与 Blanco Cigars 的履约协议结束两周后，公司宣布全部产品线转到 PDR。弗洛雷斯对行业媒体说，他们想只与他一家合作，不要别的工厂。

本图集的 PDR 词条已经点了它的名；这一条把环扣上。Entered Apprentice 与 Veiled Prophet 有一个少有词条能写的特点：配方里有巴拉圭烟叶。',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"大师等级——主打系列，2022年起在 PDR 卷制。"},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"入门学徒——配方里有巴拉圭烟叶。"},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2021年2月——与阿贝·弗洛雷斯合作调配的首支雪茄。"}]',
        'هيرام آند سولومون علامةٌ كُتبت للماسونيين، بأيدي ماسونيين: حيرام أبيف، المهندس الأسطوري للهيكل، وسليمان، الملك الذي أمر ببنائه. أسّسها فؤاد كشوطي وجورج دقرط سنة 2015، والخطوط تحمل أسماء درجات المحفل ومناصبه — Entered Apprentice وFellow Craft وMaster Mason وGrand Architect وShriner وVeiled Prophet وTraveling Man. الفكرة، كما تقول الدار، أن يجتمع الإخوة حول سيجار. لا تحكم البطاقة على الفكرة؛ بل تسجّل أنّها صمدت عشر سنين.

ما على هذا الأطلس إثباته هو مَن يلفّ. بدأت الدار في جمهورية الدومينيكان، ثم عهدت بقسط كبير من إنتاجها إلى Plasencia. وفي 2021 بدأ فؤاد ورومي كشوطي التركيب مع آبي فلوريس، المزّاج الرئيسي في PDR Cigars في تامبوريل — Curamus في شباط/فبراير 2021، ثم Châbal وRevival وSublime Prince 32 في مطلع 2022. وفي حزيران/يونيو 2022، بعد أسبوعين من انتهاء اتفاق التنفيذ مع Blanco Cigars، أعلنت الدار أنّ محفظتها كلّها تنتقل إلى PDR. وقال فلوريس لصحافة المهنة إنّهم أرادوا العمل معه وحده من دون مصنع آخر.

بطاقة PDR في هذا الأطلس تسمّيها من قبل؛ وهذه تُغلق الحلقة. ولِـEntered Apprentice وVeiled Prophet خصوصيةٌ قلّما تستطيع بطاقة كتابتها: تبغ باراغوياني في المزجة.',
        '[{"name":"Master Mason","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"درجة المعلّم — الخطّ الرئيسي، يُلفّ لدى PDR منذ 2022."},{"name":"Entered Apprentice","color":"#C9A96E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"المتدرّب الداخل — تبغ باراغوياني في المزجة."},{"name":"Curamus","color":"#7A2E1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"شباط/فبراير 2021 — أوّل سيجار رُكّب مع آبي فلوريس."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Epic Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Epic Cigars',
        'dominican',
        '2010 — Dean Parsons ; chez Tabacalera von Eicken',
        'Sans usine — Tabacalera von Eicken (ex-Charles Fairmorn), Santiago',
        'cigarlifeguy.com « Interview: Dean Parsons, Founder of Epic Cigars » (Canadien, dix ans dans la police, parti en 2005 aux Turks et Caicos ; marque Turks Select 2006-2010 ; installé en Rép. dominicaine en 2009, lance Epic en 2010 avec Maduro et Corojo, toujours au catalogue ; distribuée au Canada depuis 2015) ; halfwheel.com « Epic Corojo Reserva Double Corona » et « Epic Maduro Reserva Robusto » (roulés à la fabrique Charles Fairmorn, qui fait aussi Kristoff ; Corojo d''Équateur et Arapiraca du Brésil) ; cigar-coop.com « Summer of ''20 Spotlight: Epic Cigars/Nat Cicco » (Zander-Greg, distributeur californien propriétaire de Nat Cicco depuis 2007, rachète Epic fin 2019 et garde Parsons) ; epiccigars.com',
        'Epic est née d''un policier canadien devenu agent immobilier aux Caraïbes. Dean Parsons a quitté dix ans de police en 2005 pour les îles Turks et Caicos, où l''on trouvait mal de bons cigares ; il allait en chercher en République dominicaine pour les offrir à ses clients, y a rencontré de petites fabriques, et a lancé une première marque réservée aux îles, Turks Select, de 2006 à 2010. Installé à Santiago en 2009, il a fondé Epic en 2010 avec deux cigares, un Maduro et un Corojo, qui sont toujours au catalogue.

La fabrique est celle qui roule Kristoff, dont l''atlas porte la fiche : Charles Fairmorn, à Santiago, devenue Tabacalera von Eicken. Le Corojo Reserva porte une cape corojo d''Équateur, le Maduro Reserva une Arapiraca du Brésil. Fin 2019, Zander-Greg, le distributeur californien qui possède Nat Cicco depuis 2007, a racheté Epic et gardé Parsons à sa tête — il dit que peu de choses ont changé pour lui, sinon les volumes et les marchés.

Une marque fondée par un étranger, roulée par une fabrique nommée, rachetée par un distributeur : trois choses que cet atlas écrit telles quelles, sans les traduire en romance.',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Corojo d''Équateur","vitolas":[],"story":"L''un des deux cigares de 2010, toujours au catalogue."},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"Arapiraca du Brésil","vitolas":[],"story":"L''autre cigare de 2010."}]',
        'Epic was born of a Canadian police officer turned real-estate agent in the Caribbean. Dean Parsons left ten years of law enforcement in 2005 for the Turks and Caicos Islands, where good cigars were hard to find; he went to buy them in the Dominican Republic as gifts for his clients, met small factories there, and launched a first brand reserved for the islands, Turks Select, from 2006 to 2010. Settled in Santiago in 2009, he founded Epic in 2010 with two cigars, a Maduro and a Corojo, which are still in the catalogue.

The factory is the one that rolls Kristoff, whose entry this atlas carries: Charles Fairmorn, in Santiago, now Tabacalera von Eicken. The Corojo Reserva wears an Ecuadorian corojo wrapper, the Maduro Reserva a Brazilian Arapiraca. In late 2019, Zander-Greg, the California distributor that has owned Nat Cicco since 2007, bought Epic and kept Parsons at its head — he says little has changed for him, other than volumes and markets.

A brand founded by a foreigner, rolled by a named factory, bought by a distributor: three things this atlas writes as they are, without translating them into romance.',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorian corojo","vitolas":[],"story":"One of the two cigars of 2010, still in the catalogue."},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"Brazilian Arapiraca","vitolas":[],"story":"The other cigar of 2010."}]',
        'Epic nació de un policía canadiense convertido en agente inmobiliario en el Caribe. Dean Parsons dejó diez años de policía en 2005 por las islas Turcas y Caicos, donde costaba encontrar buenos puros; iba a comprarlos a la República Dominicana para regalarlos a sus clientes, conoció allí pequeñas fábricas, y lanzó una primera marca reservada a las islas, Turks Select, de 2006 a 2010. Instalado en Santiago en 2009, fundó Epic en 2010 con dos puros, un Maduro y un Corojo, que siguen en el catálogo.

La fábrica es la que lía Kristoff, cuya ficha lleva este atlas: Charles Fairmorn, en Santiago, hoy Tabacalera von Eicken. El Corojo Reserva lleva capa corojo de Ecuador, el Maduro Reserva una Arapiraca de Brasil. A finales de 2019, Zander-Greg, el distribuidor californiano que posee Nat Cicco desde 2007, compró Epic y mantuvo a Parsons al frente — él dice que poco ha cambiado para él, salvo los volúmenes y los mercados.

Una marca fundada por un extranjero, liada por una fábrica nombrada, comprada por un distribuidor: tres cosas que este atlas escribe tal cual, sin traducirlas en romance.',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Corojo de Ecuador","vitolas":[],"story":"Uno de los dos puros de 2010, aún en el catálogo."},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"Arapiraca de Brasil","vitolas":[],"story":"El otro puro de 2010."}]',
        'Epic entstand aus einem kanadischen Polizisten, der Immobilienmakler in der Karibik wurde. Dean Parsons verließ 2005 zehn Jahre Polizeidienst für die Turks- und Caicosinseln, wo gute Zigarren schwer zu finden waren; er kaufte sie in der Dominikanischen Republik als Geschenke für seine Kunden, lernte dort kleine Fabriken kennen und lancierte eine erste, den Inseln vorbehaltene Marke, Turks Select, von 2006 bis 2010. 2009 in Santiago niedergelassen, gründete er Epic 2010 mit zwei Zigarren, einer Maduro und einer Corojo, die noch im Katalog sind.

Die Fabrik ist jene, die Kristoff rollt, deren Eintrag dieser Atlas führt: Charles Fairmorn in Santiago, heute Tabacalera von Eicken. Die Corojo Reserva trägt ein ecuadorianisches Corojo-Deckblatt, die Maduro Reserva eine brasilianische Arapiraca. Ende 2019 kaufte Zander-Greg, der kalifornische Distributor, dem Nat Cicco seit 2007 gehört, Epic und behielt Parsons an der Spitze — er sagt, für ihn habe sich wenig geändert, außer Mengen und Märkten.

Eine von einem Ausländer gegründete Marke, gerollt von einer benannten Fabrik, gekauft von einem Distributor: drei Dinge, die dieser Atlas so schreibt, wie sie sind, ohne sie in Romantik zu übersetzen.',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuadorianisches Corojo","vitolas":[],"story":"Eine der beiden Zigarren von 2010, noch im Katalog."},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"Brasilianische Arapiraca","vitolas":[],"story":"Die andere Zigarre von 2010."}]',
        'Epic 诞生于一位转行到加勒比做房地产经纪的加拿大警察。迪恩·帕森斯2005年结束十年警察生涯，去了特克斯和凯科斯群岛，那里好雪茄难寻；他到多米尼加共和国买雪茄送给客户，在那里结识了小工厂，并推出一个只在群岛销售的品牌 Turks Select，从2006到2010年。2009年定居圣地亚哥后，他2010年创办 Epic，以 Maduro 与 Corojo 两支雪茄起步，至今仍在目录中。

工厂就是卷制 Kristoff 的那家——本图集载有 Kristoff 词条：圣地亚哥的 Charles Fairmorn，今名 Tabacalera von Eicken。Corojo Reserva 用厄瓜多尔 corojo 茄衣，Maduro Reserva 用巴西 Arapiraca。2019年底，2007年起拥有 Nat Cicco 的加州经销商 Zander-Greg 收购了 Epic，并留帕森斯掌舵——他说对他而言变化不大，除了产量与市场。

一个由外国人创办、由点名的工厂卷制、被经销商收购的品牌：三件事本图集照实写下，不译成传奇。',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔 corojo","vitolas":[],"story":"2010年两支雪茄之一，至今仍在目录中。"},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"巴西 Arapiraca","vitolas":[],"story":"2010年的另一支雪茄。"}]',
        'وُلدت إيبيك من شرطي كندي صار وكيل عقارات في الكاريبي. ترك دين بارسونز عشر سنوات من الشرطة سنة 2005 إلى جزر تركس وكايكوس حيث يصعب إيجاد سيجار جيّد؛ فكان يذهب لشرائه من جمهورية الدومينيكان هديّةً لزبائنه، وتعرّف هناك إلى مصانع صغيرة، وأطلق علامة أولى مقصورة على الجزر، Turks Select، من 2006 إلى 2010. وبعد استقراره في سانتياغو سنة 2009 أسّس إيبيك سنة 2010 بسيجارين، Maduro وCorojo، ما زالا في الكتالوج.

المصنع هو الذي يلفّ Kristoff التي يحمل هذا الأطلس بطاقتها: Charles Fairmorn في سانتياغو، الذي صار Tabacalera von Eicken. يحمل Corojo Reserva غلاف كوروخو إكوادوريًّا، وMaduro Reserva غلاف أرابيراكا برازيليًّا. وفي أواخر 2019 اشترت Zander-Greg، الموزّع الكاليفورني الذي يملك Nat Cicco منذ 2007، إيبيك وأبقت بارسونز على رأسها — ويقول إنّ قليلًا تغيّر بالنسبة إليه، سوى الكمّيات والأسواق.

علامةٌ أسّسها أجنبي، ولفّها مصنع مسمّى، واشتراها موزّع: ثلاثة أشياء يكتبها هذا الأطلس كما هي، من دون ترجمتها إلى رومانسية.',
        '[{"name":"Corojo Reserva","color":"#8B5A2B","force":"Medium-Full","wrapper":"كوروخو إكوادوري","vitolas":[],"story":"أحد سيجارَي 2010، ما زال في الكتالوج."},{"name":"Maduro Reserva","color":"#3A2A1E","force":"Full","wrapper":"أرابيراكا برازيلي","vitolas":[],"story":"السيجار الآخر من 2010."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Chogüí ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Chogüí',
        'dominican',
        '2014 — Víctor Nicolás ; chez Manufactura Rivas',
        'Sans usine — Manufactura Rivas (Francisco « Chico » Rivas), Rép. dominicaine',
        'halfwheel.com « Chogüí Dos77 Corojo Rogusto » (2 juin 2022 : marque de Víctor Nicolás, fumeur dominicain qui a voulu faire ses cigares avec les tabacs de Leo Reyes et la petite fabrique de Francisco « Chico » Rivas, surnommée le nid secret d''après l''oiseau de la marque ; Primera Edición lancée en 2014 ; Nicolás quitte le métier en 2018 ; retour annoncé en février 2022 avec un Dos77 refait — cape corojo dominicaine cultivée au soleil, piloto mejorado dans la tripe — distribué par Venture 1492, la société de Kyle Gellis de Warped ; la maison dit tirer fierté de ses cigares 100 % dominicains) ; smallbatchcigar.com « Interview with Chogui Cigars (Victor Nicolas) » (Primera Edición, novembre 2014, réservée aux détaillants dominicains, 6 000 cigares ; rencontre avec Rivas fin 2013)',
        'Le chogüí est un oiseau de la République dominicaine, et la marque qui porte son nom est celle d''un amateur du pays, Víctor Nicolás, qui a voulu faire ses propres cigares. Il a rencontré Francisco « Chico » Rivas à la fin de 2013 et s''est mis à visiter sa petite fabrique chaque mois — Manufactura Rivas, que la maison a surnommée le nid secret, d''après l''oiseau. Les tabacs venaient de Leo Reyes, le planteur de Navarrete dont l''atlas raconte la ferme à la fiche De Los Reyes. La Primera Edición est sortie en novembre 2014, réservée aux détaillants dominicains, à six mille cigares.

L''atlas la classe ici pour ce qu''elle est : un puro dominicain, tabacs, fabrique et fondateur du même pays. C''est plus rare qu''on ne le croit dans un pays qui roule surtout pour les autres.

En 2018, Nicolás a quitté le métier sans bruit, et son distributeur américain lui-même ne savait pas ce qu''il advenait de la marque. Elle est revenue en février 2022, avec un Dos77 refait — la cape dominicaine d''origine était introuvable, remplacée par un corojo dominicain cultivé au soleil, avec du piloto mejorado dans la tripe — et une distribution confiée à Venture 1492, la société de Kyle Gellis, le fondateur de Warped, dont l''atlas porte la fiche. Une marque dormante puis revenue, comme Mombacho l''a été dans l''autre sens : la fiche l''écrit au présent parce que le retour est documenté.',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"Corojo dominicain cultivé au soleil","vitolas":[],"story":"Le cigare du retour, avril 2022, refait avec du piloto mejorado dans la tripe. Un seul format, le « rogusto », entre robusto et gusto."},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"Dominicaine","vitolas":[],"story":"Novembre 2014, six mille cigares, réservés aux détaillants dominicains."}]',
        'The chogüí is a bird of the Dominican Republic, and the brand that bears its name is that of an enthusiast from the country, Víctor Nicolás, who wanted to make his own cigars. He met Francisco "Chico" Rivas at the end of 2013 and began visiting his small factory every month — Manufactura Rivas, which the house nicknamed the secret nest, after the bird. The tobaccos came from Leo Reyes, the Navarrete grower whose farm this atlas tells at the De Los Reyes entry. The Primera Edición came out in November 2014, reserved for Dominican retailers, at six thousand cigars.

This atlas classifies it here for what it is: a Dominican puro, tobaccos, factory and founder from the same country. That is rarer than one thinks in a country that mostly rolls for others.

In 2018, Nicolás left the trade quietly, and even his American distributor did not know what was becoming of the brand. It came back in February 2022, with a remade Dos77 — the original Dominican wrapper could not be found, replaced by a sun-grown Dominican corojo, with piloto mejorado in the filler — and distribution entrusted to Venture 1492, the company of Kyle Gellis, the founder of Warped, whose entry this atlas carries. A brand dormant then returned, as Mombacho was the other way round: the entry writes it in the present because the return is documented.',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sun-grown Dominican corojo","vitolas":[],"story":"The return cigar, April 2022, remade with piloto mejorado in the filler. A single size, the rogusto, between robusto and gusto."},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"Dominican","vitolas":[],"story":"November 2014, six thousand cigars, reserved for Dominican retailers."}]',
        'El chogüí es un ave de la República Dominicana, y la marca que lleva su nombre es la de un aficionado del país, Víctor Nicolás, que quiso hacer sus propios puros. Conoció a Francisco «Chico» Rivas a finales de 2013 y empezó a visitar su pequeña fábrica cada mes — Manufactura Rivas, que la casa apodó el nido secreto, por el ave. Los tabacos venían de Leo Reyes, el cultivador de Navarrete cuya finca este atlas cuenta en la ficha De Los Reyes. La Primera Edición salió en noviembre de 2014, reservada a los minoristas dominicanos, con seis mil puros.

Este atlas la clasifica aquí por lo que es: un puro dominicano, tabacos, fábrica y fundador del mismo país. Es más raro de lo que se cree en un país que lía sobre todo para otros.

En 2018, Nicolás dejó el oficio sin ruido, y ni su distribuidor estadounidense sabía qué era de la marca. Volvió en febrero de 2022, con un Dos77 rehecho — la capa dominicana original no se encontraba, sustituida por un corojo dominicano cultivado al sol, con piloto mejorado en la tripa — y una distribución confiada a Venture 1492, la sociedad de Kyle Gellis, el fundador de Warped, cuya ficha lleva este atlas. Una marca dormida y luego vuelta, como Mombacho lo fue en sentido contrario: la ficha la escribe en presente porque el regreso está documentado.',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"Corojo dominicano cultivado al sol","vitolas":[],"story":"El puro del regreso, abril de 2022, rehecho con piloto mejorado en la tripa. Un solo formato, el rogusto, entre robusto y gusto."},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"Dominicana","vitolas":[],"story":"Noviembre de 2014, seis mil puros, reservados a los minoristas dominicanos."}]',
        'Der Chogüí ist ein Vogel der Dominikanischen Republik, und die Marke, die seinen Namen trägt, ist die eines Liebhabers aus dem Land, Víctor Nicolás, der seine eigenen Zigarren machen wollte. Er traf Francisco „Chico" Rivas Ende 2013 und begann, dessen kleine Fabrik jeden Monat zu besuchen — Manufactura Rivas, die das Haus nach dem Vogel das geheime Nest nannte. Die Tabake kamen von Leo Reyes, dem Pflanzer aus Navarrete, dessen Farm dieser Atlas im Eintrag De Los Reyes erzählt. Die Primera Edición erschien im November 2014, den dominikanischen Händlern vorbehalten, mit sechstausend Zigarren.

Dieser Atlas ordnet sie hier ein für das, was sie ist: ein dominikanischer Puro, Tabake, Fabrik und Gründer aus demselben Land. Das ist seltener, als man denkt, in einem Land, das vor allem für andere rollt.

2018 verließ Nicolás das Metier still, und selbst sein amerikanischer Distributor wusste nicht, was aus der Marke wurde. Sie kam im Februar 2022 zurück, mit einer neu gemachten Dos77 — das ursprüngliche dominikanische Deckblatt war nicht zu finden, ersetzt durch ein sonnengereiftes dominikanisches Corojo, mit Piloto Mejorado in der Einlage — und einem Vertrieb durch Venture 1492, die Gesellschaft von Kyle Gellis, dem Gründer von Warped, dessen Eintrag dieser Atlas führt. Eine schlafende und dann zurückgekehrte Marke, wie Mombacho es umgekehrt war: Der Eintrag schreibt sie im Präsens, weil die Rückkehr dokumentiert ist.',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"Sonnengereiftes dominikanisches Corojo","vitolas":[],"story":"Die Zigarre der Rückkehr, April 2022, neu gemacht mit Piloto Mejorado in der Einlage. Ein einziges Format, der Rogusto, zwischen Robusto und Gusto."},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"Dominikanisch","vitolas":[],"story":"November 2014, sechstausend Zigarren, den dominikanischen Händlern vorbehalten."}]',
        'chogüí 是多米尼加共和国的一种鸟，以它命名的品牌属于本国的一位爱好者——维克托·尼古拉斯，他想做自己的雪茄。2013年底他结识了弗朗西斯科·「奇科」·里瓦斯，开始每月造访他的小工厂——Manufactura Rivas，公司借那只鸟的名义称之为秘密鸟巢。烟叶来自纳瓦雷特的种植者莱奥·雷耶斯，本图集在 De Los Reyes 词条讲过他的农场。Primera Edición 于2014年11月推出，只供多米尼加零售商，六千支。

本图集据实把它归于此：一支多米尼加纯料，烟叶、工厂与创始人同出一国。在一个主要为他人卷制的国家，这比人们以为的更少见。

2018年，尼古拉斯悄然离开行业，连他的美国经销商也不知道品牌的去向。2022年2月它回来了，带着重做的 Dos77——原来的多米尼加茄衣已无处可寻，改用日晒多米尼加 corojo，填充里加了 piloto mejorado——分销交给 Venture 1492，即 Warped 创始人凯尔·盖利斯的公司，本图集载有 Warped 词条。一个沉睡后归来的品牌，正如 Mombacho 走的反方向：词条以现在时写它，因为回归有据可查。',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"日晒多米尼加 corojo","vitolas":[],"story":"回归之作，2022年4月，填充加入 piloto mejorado 重做。单一尺寸 rogusto，介于 robusto 与 gusto 之间。"},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"多米尼加","vitolas":[],"story":"2014年11月，六千支，只供多米尼加零售商。"}]',
        'التشوغي طائرٌ من جمهورية الدومينيكان، والعلامة التي تحمل اسمه هي علامة هاوٍ من البلد، فيكتور نيكولاس، أراد أن يصنع سيجاراته بنفسه. التقى فرانسيسكو «تشيكو» ريفاس في أواخر 2013 وراح يزور مصنعه الصغير كلّ شهر — Manufactura Rivas، الذي لقّبته الدار بالعشّ السرّي نسبةً إلى الطائر. وجاءت الأتبغة من ليو رييس، مزارع نافاريتي الذي يروي هذا الأطلس مزرعته في بطاقة De Los Reyes. صدرت Primera Edición في تشرين الثاني/نوفمبر 2014، مقصورةً على تجّار التجزئة الدومينيكيين، بستّة آلاف سيجار.

يصنّفها هذا الأطلس هنا على ما هي: سيجار دومينيكي خالص، أتبغة ومصنع ومؤسّس من البلد نفسه. وذلك نادرٌ خلافًا لما يُظنّ في بلد يلفّ للآخرين في الغالب.

في 2018 ترك نيكولاس المهنة بلا ضجيج، وحتى موزّعه الأمريكي لم يكن يعرف ما يحلّ بالعلامة. عادت في شباط/فبراير 2022 بسيجار Dos77 معاد الصنع — الغلاف الدومينيكي الأصلي لم يُعثر عليه، فاستُبدل به كوروخو دومينيكي مزروع تحت الشمس، مع بيلوتو ميخورادو في الحشوة — وتوزيعٍ عُهد به إلى Venture 1492، شركة كايل غيليس، مؤسّس Warped التي يحمل هذا الأطلس بطاقتها. علامةٌ نامت ثم عادت، كما كانت Mombacho في الاتجاه المعاكس: تكتبها البطاقة بصيغة الحاضر لأنّ العودة موثّقة.',
        '[{"name":"Dos77","color":"#8B5A2B","force":"Medium-Full","wrapper":"كوروخو دومينيكي مزروع تحت الشمس","vitolas":[],"story":"سيجار العودة، نيسان/أبريل 2022، أُعيد صنعه مع بيلوتو ميخورادو في الحشوة. قياس واحد، الـrogusto، بين الروبوستو والغوستو."},{"name":"Primera Edición","color":"#5B3A29","force":"Medium","wrapper":"دومينيكي","vitolas":[],"story":"تشرين الثاني/نوفمبر 2014، ستّة آلاف سيجار، مقصورة على تجّار التجزئة الدومينيكيين."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Principle Cigars ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Principle Cigars',
        'dominican',
        '2013 — Darren Cioffi ; chez KBF',
        'Sans usine — Kelner Boutique Factory (Hendrik Kelner Jr.), Santiago ; Casa Carrillo pour Time To Burn',
        'principletrading.com « About Principle Cigars » (Darren Cioffi, chasseur de trésors et collectionneur d''étiquettes de boîtes anciennes, avec une bibliothèque de cigares remontant aux années 1870 ; un an et demi de sélection de tabacs avec Hendrik Kelner Jr. ; roulage à la Kelner Boutique Factory de Santiago par quatre rouleurs, jusqu''à dix cigares par jour pour certaines vitoles) ; wina-mp.pl (fondée en 2013 — devise de la maison « Pleasing All Senses Since 2013 » ; Time To Burn, projet des dix ans en 2023, fait à Casa Carrillo) ; cigarlifeguy.com « From Passion to Principle Cigars » (Aviator, art déco industriel américain de la fin des années 1940 ; Accomplice, style français des années 1930 ; Martinique, colonial du XVIIIe siècle) ; halfwheel.com « Principle Cigars Releases Engagement », « Principle Martinique Corona »',
        'Principle est une maison de collectionneur. Darren Cioffi, de Long Island, a passé des années à manier des étiquettes de boîtes anciennes et des lithographies de tabac, et s''est constitué une bibliothèque de cigares qui remonte aux années 1870 ; il en a fumé d''anciens et d''avant l''embargo. La marque qu''il a fondée en 2013 — sa devise le date — est née de cette manie : le cigare comme objet entier, boîte, bague, format et tabac ensemble.

Il a rencontré Hendrik Kelner Jr., le fils du maître de tabac de Davidoff, qui venait d''ouvrir son propre atelier à Santiago — la Kelner Boutique Factory, dont l''atlas porte la fiche. Ils ont passé un an et demi à choisir des tabacs vieillis, et c''est là que tout est roulé, par quatre rouleurs, à raison de dix cigares par jour pour les formats les plus lents. Time To Burn, le projet des dix ans, en 2023, a fait exception : il est sorti de Casa Carrillo. La fiche KBF nommait déjà Principle ; celle-ci lui rend la référence.

Les lignes sont des époques : Aviator, l''art déco industriel américain de la fin des années 1940 ; Accomplice, le style français des années 1930 ; Martinique, le colonial du XVIIIe siècle. Une maison qui pense ses bagues comme des estampes — c''est ce que le fondateur collectionnait avant de produire.',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''art déco industriel américain de la fin des années 1940 — la ligne des débuts, cinq à sept tabacs vieillis."},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Le style français des années 1930 — un même assemblage sur toutes les vitoles, bagues de satin."},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le colonial du XVIIIe siècle."}]',
        'Principle is a collector''s house. Darren Cioffi, of Long Island, spent years handling antique box labels and tobacco lithographs, and built a cigar library going back to the 1870s; he has smoked aged and pre-embargo examples. The brand he founded in 2013 — its motto dates it — was born of that mania: the cigar as a whole object, box, band, size and tobacco together.

He met Hendrik Kelner Jr., the son of Davidoff''s tobacco master, who had just opened his own workshop in Santiago — Kelner Boutique Factory, whose entry this atlas carries. They spent a year and a half choosing aged tobaccos, and that is where everything is rolled, by four rollers, at ten cigars a day for the slowest sizes. Time To Burn, the tenth-anniversary project, in 2023, was the exception: it came out of Casa Carrillo. The KBF entry already named Principle; this one returns the reference.

The lines are eras: Aviator, American industrial art deco of the late 1940s; Accomplice, French style of the 1930s; Martinique, eighteenth-century colonial. A house that thinks its bands as prints — that is what the founder collected before producing.',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"American industrial art deco of the late 1940s — the founding line, five to seven aged tobaccos."},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"French style of the 1930s — one blend across all vitolas, satin bands."},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"Eighteenth-century colonial."}]',
        'Principle es una casa de coleccionista. Darren Cioffi, de Long Island, pasó años manejando etiquetas de cajas antiguas y litografías de tabaco, y reunió una biblioteca de puros que se remonta a la década de 1870; ha fumado ejemplares añejos y de antes del embargo. La marca que fundó en 2013 — su lema la fecha — nació de esa manía: el puro como objeto entero, caja, anilla, formato y tabaco juntos.

Conoció a Hendrik Kelner Jr., el hijo del maestro de tabaco de Davidoff, que acababa de abrir su propio taller en Santiago — la Kelner Boutique Factory, cuya ficha lleva este atlas. Pasaron un año y medio eligiendo tabacos añejos, y allí se lía todo, por cuatro torcedores, a razón de diez puros al día para los formatos más lentos. Time To Burn, el proyecto de los diez años, en 2023, fue la excepción: salió de Casa Carrillo. La ficha KBF ya nombraba a Principle; esta le devuelve la referencia.

Las líneas son épocas: Aviator, el art déco industrial estadounidense de finales de los años 1940; Accomplice, el estilo francés de los años 1930; Martinique, el colonial del siglo XVIII. Una casa que piensa sus anillas como estampas — es lo que el fundador coleccionaba antes de producir.',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El art déco industrial estadounidense de finales de los años 1940 — la línea inicial, de cinco a siete tabacos añejos."},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El estilo francés de los años 1930 — una misma ligada en todas las vitolas, anillas de satén."},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El colonial del siglo XVIII."}]',
        'Principle ist ein Sammlerhaus. Darren Cioffi aus Long Island verbrachte Jahre damit, antike Kistenetiketten und Tabaklithografien zu handhaben, und baute eine Zigarrenbibliothek auf, die bis in die 1870er zurückreicht; er hat gealterte Exemplare und solche von vor dem Embargo geraucht. Die Marke, die er 2013 gründete — ihr Motto datiert sie —, entstand aus dieser Manie: die Zigarre als ganzes Objekt, Kiste, Bauchbinde, Format und Tabak zusammen.

Er traf Hendrik Kelner Jr., den Sohn des Tabakmeisters von Davidoff, der gerade seine eigene Werkstatt in Santiago eröffnet hatte — die Kelner Boutique Factory, deren Eintrag dieser Atlas führt. Sie verbrachten anderthalb Jahre mit der Auswahl gealterter Tabake, und dort wird alles gerollt, von vier Rollern, mit zehn Zigarren pro Tag bei den langsamsten Formaten. Time To Burn, das Projekt zum zehnjährigen Bestehen 2023, war die Ausnahme: Es kam aus Casa Carrillo. Der KBF-Eintrag nannte Principle bereits; dieser erwidert den Verweis.

Die Linien sind Epochen: Aviator, amerikanisches industrielles Art déco der späten 1940er; Accomplice, französischer Stil der 1930er; Martinique, Kolonialstil des 18. Jahrhunderts. Ein Haus, das seine Bauchbinden als Drucke denkt — das sammelte der Gründer, bevor er produzierte.',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Amerikanisches industrielles Art déco der späten 1940er — die Gründungslinie, fünf bis sieben gealterte Tabake."},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Französischer Stil der 1930er — ein Blend über alle Vitolas, Satin-Bauchbinden."},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Kolonialstil des 18. Jahrhunderts."}]',
        'Principle 是一家收藏家的公司。长岛的达伦·乔菲多年经手古董雪茄盒标签与烟草石版画，建起一座可追溯至1870年代的雪茄库；他抽过陈年与禁运前的雪茄。他2013年创办的品牌——公司的座右铭标出了年份——生于这种癖好：雪茄作为完整的物件，盒、茄标、尺寸与烟叶一体。

他结识了大卫杜夫烟草大师之子小亨德里克·克尔纳，后者刚在圣地亚哥开了自己的作坊——Kelner Boutique Factory，本图集载有其词条。两人花一年半挑选陈年烟叶，一切都在那里由四位卷工卷制，速度慢的尺寸每天只出十支。2023年的十周年项目 Time To Burn 是例外：它出自 Casa Carrillo。KBF 词条已点了 Principle 的名；这一条把引用还回去。

各系列是不同年代：Aviator，1940年代末的美国工业装饰艺术；Accomplice，1930年代的法国风格；Martinique，十八世纪殖民地风格。一家把茄标当版画来构思的公司——创始人在生产之前收藏的正是这些。',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"未公开","vitolas":[],"story":"1940年代末的美国工业装饰艺术——创始系列，五到七种陈年烟叶。"},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"未公开","vitolas":[],"story":"1930年代的法国风格——所有尺寸同一配方，缎面茄标。"},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"十八世纪殖民地风格。"}]',
        'برينسيبل دارُ جامعِ تحف. قضى دارن تشوفي، من لونغ آيلاند، سنواتٍ يتداول ملصقات علب قديمة وطبعات حجرية للتبغ، وكوّن مكتبة سيجار تعود إلى سبعينيات القرن التاسع عشر؛ ودخّن نماذج معتّقة ومن قبل الحظر. العلامة التي أسّسها سنة 2013 — وشعارها يؤرّخها — وُلدت من هذا الهوس: السيجار بوصفه شيئًا كاملًا، العلبة والحزام والقياس والتبغ معًا.

التقى هندريك كلنر الابن، ابن معلّم التبغ عند دافيدوف، الذي كان قد افتتح للتوّ ورشته الخاصة في سانتياغو — Kelner Boutique Factory التي يحمل هذا الأطلس بطاقتها. قضيا سنة ونصفًا في اختيار أتبغة معتّقة، وهناك يُلفّ كلّ شيء، بأيدي أربعة لفّافين، بمعدّل عشر سيجارات في اليوم للقياسات الأبطأ. وكان Time To Burn، مشروع السنوات العشر سنة 2023، الاستثناء: خرج من Casa Carrillo. بطاقة KBF كانت تسمّي برينسيبل من قبل؛ وهذه تردّ لها الإحالة.

الخطوط حِقَب: Aviator، الآرت ديكو الصناعي الأمريكي لأواخر الأربعينيات؛ Accomplice، الطراز الفرنسي للثلاثينيات؛ Martinique، الطراز الاستعماري للقرن الثامن عشر. دارٌ تفكّر في أحزمتها كما في المطبوعات — وهذا ما كان المؤسّس يجمعه قبل أن ينتج.',
        '[{"name":"Aviator Series","color":"#3E4A6B","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الآرت ديكو الصناعي الأمريكي لأواخر الأربعينيات — خطّ البدايات، خمسة إلى سبعة أتبغة معتّقة."},{"name":"Accomplice","color":"#7A2E1E","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الطراز الفرنسي للثلاثينيات — مزجة واحدة لكلّ الفيتولات، أحزمة من الساتان."},{"name":"Martinique","color":"#8B5A2B","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الطراز الاستعماري للقرن الثامن عشر."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Bombay Tobak ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Bombay Tobak',
        'costarica',
        'Mai 2014 — Mel Shah ; chez Tabacos de Costa Rica',
        'Sans usine — Tabacos de Costa Rica S.A. (ex-Vegas de Santiago), Puriscal',
        'cigaraficionado.com « Bombay Tobak Ships M.Esteli » (30 août 2019 : Mel Shah, propriétaire ; M.Estelí, sa ligne la plus corsée, cape Habano 2000 d''Équateur, sous-cape dominicaine, tripe surtout nicaraguayenne avec du Piloto Cubano ; comme tous les cigares de la maison, produite à la fabrique Tabacos de Costa Rica) et « MBombay Puts Cigars In A Can » (fondée en mai 2014 par Mel Shah, propriétaire du Fame Lounge de Palm Springs, pour distribuer nationalement ses cigares maison) ; halfwheel.com « MBombay Gaaja » (juillet 2016, un seul format toro pressé 6 × 54, du mot gaja — l''éléphant de la culture hindoue) ; cigar-coop.com « Cigar Review: MBombay Classic Torpedo » (Connecticut d''Équateur, tripes du Nicaragua, du Pérou et de Rép. dominicaine)',
        'Bombay Tobak est la maison de Mel Shah, propriétaire du Fame Lounge de Palm Springs, en Californie — un bar à cigares, à vins et à bières. Il a fondé la société en mai 2014 pour distribuer dans tout le pays les cigares qu''il faisait faire pour sa maison, sous la marque MBombay. Le nom dit l''origine indienne du fondateur, et les lignes la disent aussi : Gaaja, en juillet 2016, vient de gaja, l''éléphant de la culture hindoue ; Kēsara est le safran ; Mōra, le paon.

Tout est roulé au Costa Rica, à Puriscal, chez Tabacos de Costa Rica — la fabrique que l''atlas décrit à la fiche Vegas de Santiago, son ancien nom, et qui roule aussi Villa Casdagli et les bagues de Zechbauer. MBombay est donc la troisième marque de cet atlas à sortir de cet atelier, et la fiche Vegas de Santiago le dit désormais. Le Costa Rica reste, ici encore, un pays d''atelier : les tabacs viennent d''ailleurs — Équateur, République dominicaine, Pérou, Nicaragua.

La ligne Classic, en Connecticut d''Équateur, est la plus douce ; M.Estelí, en 2019, la plus corsée de la maison, en Habano 2000 d''Équateur sur tripe surtout nicaraguayenne. Le nom d''Estelí sur un cigare roulé au Costa Rica est une dette envers le tabac, pas envers l''atelier — la fiche le précise parce que la règle de l''atlas est le lieu de roulage.',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"La ligne la plus douce — tripes du Nicaragua, du Pérou et de République dominicaine."},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Juillet 2016 — l''éléphant, gaja ; un seul format à l''origine, un toro pressé 6 × 54."},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"Habano 2000 d''Équateur","vitolas":[],"story":"2019 — la plus corsée de la maison, tripe surtout nicaraguayenne, pied non coupé. Roulée au Costa Rica malgré le nom."}]',
        'Bombay Tobak is the house of Mel Shah, owner of the Fame Lounge in Palm Springs, California — a cigar, wine and beer bar. He founded the company in May 2014 to distribute nationally the cigars he had made for his lounge, under the MBombay brand. The name states the founder''s Indian origin, and so do the lines: Gaaja, in July 2016, comes from gaja, the elephant of Hindu culture; Kēsara is saffron; Mōra, the peacock.

Everything is rolled in Costa Rica, in Puriscal, at Tabacos de Costa Rica — the factory this atlas describes at the Vegas de Santiago entry, its former name, and which also rolls Villa Casdagli and Zechbauer''s bands. MBombay is thus the third brand of this atlas to come out of that workshop, and the Vegas de Santiago entry now says so. Costa Rica remains, here too, a workshop country: the tobaccos come from elsewhere — Ecuador, the Dominican Republic, Peru, Nicaragua.

The Classic line, in Ecuadorian Connecticut, is the mildest; M.Estelí, in 2019, the house''s fullest, in Ecuadorian Habano 2000 over mostly Nicaraguan filler. The name of Estelí on a cigar rolled in Costa Rica is a debt to the tobacco, not to the workshop — the entry says so because the atlas''s rule is the rolling place.',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"The mildest line — fillers from Nicaragua, Peru and the Dominican Republic."},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"July 2016 — the elephant, gaja; a single size at first, a box-pressed 6 × 54 toro."},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"Ecuadorian Habano 2000","vitolas":[],"story":"2019 — the house''s fullest, mostly Nicaraguan filler, uncut foot. Rolled in Costa Rica despite the name."}]',
        'Bombay Tobak es la casa de Mel Shah, propietario del Fame Lounge de Palm Springs, California — un bar de puros, vinos y cervezas. Fundó la sociedad en mayo de 2014 para distribuir en todo el país los puros que mandaba hacer para su local, bajo la marca MBombay. El nombre dice el origen indio del fundador, y las líneas también: Gaaja, en julio de 2016, viene de gaja, el elefante de la cultura hindú; Kēsara es el azafrán; Mōra, el pavo real.

Todo se lía en Costa Rica, en Puriscal, en Tabacos de Costa Rica — la fábrica que este atlas describe en la ficha Vegas de Santiago, su antiguo nombre, y que lía también Villa Casdagli y las anillas de Zechbauer. MBombay es pues la tercera marca de este atlas que sale de ese taller, y la ficha Vegas de Santiago lo dice desde ahora. Costa Rica sigue siendo, aquí también, un país de taller: los tabacos vienen de otra parte — Ecuador, República Dominicana, Perú, Nicaragua.

La línea Classic, en Connecticut de Ecuador, es la más suave; M.Estelí, en 2019, la más corsada de la casa, en Habano 2000 de Ecuador sobre tripa sobre todo nicaragüense. El nombre de Estelí en un puro liado en Costa Rica es una deuda con el tabaco, no con el taller — la ficha lo precisa porque la regla del atlas es el lugar de liado.',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"La línea más suave — tripas de Nicaragua, Perú y República Dominicana."},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"Julio de 2016 — el elefante, gaja; un solo formato al principio, un toro prensado 6 × 54."},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"Habano 2000 de Ecuador","vitolas":[],"story":"2019 — la más corsada de la casa, tripa sobre todo nicaragüense, pie sin cortar. Liada en Costa Rica pese al nombre."}]',
        'Bombay Tobak ist das Haus von Mel Shah, Besitzer der Fame Lounge in Palm Springs, Kalifornien — eine Zigarren-, Wein- und Bierbar. Er gründete die Gesellschaft im Mai 2014, um die Zigarren, die er für sein Lokal machen ließ, landesweit zu vertreiben, unter der Marke MBombay. Der Name sagt die indische Herkunft des Gründers, und die Linien sagen sie auch: Gaaja, im Juli 2016, kommt von gaja, dem Elefanten der hinduistischen Kultur; Kēsara ist der Safran; Mōra, der Pfau.

Alles wird in Costa Rica gerollt, in Puriscal, bei Tabacos de Costa Rica — der Fabrik, die dieser Atlas im Eintrag Vegas de Santiago beschreibt, ihrem früheren Namen, und die auch Villa Casdagli und die Bauchbinden von Zechbauer rollt. MBombay ist damit die dritte Marke dieses Atlas aus dieser Werkstatt, und der Eintrag Vegas de Santiago sagt es nun. Costa Rica bleibt auch hier ein Werkstattland: Die Tabake kommen von anderswo — Ecuador, Dominikanische Republik, Peru, Nicaragua.

Die Linie Classic, in ecuadorianischem Connecticut, ist die mildeste; M.Estelí, 2019, die kräftigste des Hauses, in ecuadorianischem Habano 2000 über überwiegend nicaraguanischer Einlage. Der Name Estelí auf einer in Costa Rica gerollten Zigarre ist eine Schuld gegenüber dem Tabak, nicht gegenüber der Werkstatt — der Eintrag sagt es, weil die Regel des Atlas der Rollort ist.',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Die mildeste Linie — Einlage aus Nicaragua, Peru und der Dominikanischen Republik."},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Juli 2016 — der Elefant, gaja; anfangs ein einziges Format, ein gepresster Toro 6 × 54."},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"Ecuadorianisches Habano 2000","vitolas":[],"story":"2019 — die kräftigste des Hauses, überwiegend nicaraguanische Einlage, ungeschnittener Fuß. Trotz des Namens in Costa Rica gerollt."}]',
        'Bombay Tobak 是梅尔·沙阿的公司，他是加州棕榈泉 Fame Lounge 的老板——一家雪茄、葡萄酒与啤酒吧。他2014年5月成立公司，以 MBombay 品牌在全国分销原本为自家酒廊定制的雪茄。名字道出创始人的印度出身，各系列亦然：2016年7月的 Gaaja 来自 gaja，印度教文化中的大象；Kēsara 是藏红花；Mōra 是孔雀。

一切都在哥斯达黎加普里斯卡尔的 Tabacos de Costa Rica 卷制——本图集在 Vegas de Santiago 词条描述的那家工厂，那是它的旧名，它也卷制 Villa Casdagli 与 Zechbauer 的茄标。MBombay 因此是本图集第三个出自该作坊的品牌，Vegas de Santiago 词条如今已写明。哥斯达黎加在此依然是作坊之国：烟叶来自别处——厄瓜多尔、多米尼加共和国、秘鲁、尼加拉瓜。

厄瓜多尔康涅狄格茄衣的 Classic 系列最柔和；2019年的 M.Estelí 是公司里最浓烈的，厄瓜多尔 Habano 2000 茄衣配以尼加拉瓜为主的填充。一支在哥斯达黎加卷制的雪茄冠以埃斯特利之名，欠的是烟叶而非作坊——词条特意说明，因为本图集的规则是卷制地。',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"最柔和的系列——尼加拉瓜、秘鲁与多米尼加填充。"},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2016年7月——大象 gaja；起初只有一种尺寸，方压 6×54 toro。"},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"厄瓜多尔 Habano 2000","vitolas":[],"story":"2019年——公司里最浓烈的，填充以尼加拉瓜为主，茄脚不切。名字如此，仍在哥斯达黎加卷制。"}]',
        'بومباي توباك دارُ ميل شاه، صاحب Fame Lounge في بالم سبرينغز بكاليفورنيا — حانةُ سيجار ونبيذ وجعة. أسّس الشركة في أيّار/مايو 2014 ليوزّع في البلاد كلّها السيجارات التي كان يصنعها لصالونه، تحت علامة MBombay. يقول الاسم الأصل الهندي للمؤسّس، وتقوله الخطوط أيضًا: Gaaja، في تموز/يوليو 2016، من gaja، فيل الثقافة الهندوسية؛ وKēsara هو الزعفران؛ وMōra الطاووس.

كلّ شيء يُلفّ في كوستاريكا، في بوريسكال، لدى Tabacos de Costa Rica — المصنع الذي يصفه هذا الأطلس في بطاقة Vegas de Santiago، اسمه السابق، والذي يلفّ أيضًا Villa Casdagli وأحزمة Zechbauer. فـMBombay إذن العلامة الثالثة في هذا الأطلس الخارجة من تلك الورشة، وبطاقة Vegas de Santiago تقول ذلك الآن. وتبقى كوستاريكا، هنا أيضًا، بلدَ ورش: الأتبغة تأتي من مكان آخر — الإكوادور وجمهورية الدومينيكان وبيرو ونيكاراغوا.

خطّ Classic بكونيتيكت إكوادوري هو الألطف؛ وM.Estelí سنة 2019 الأقوى في الدار، بهابانو 2000 إكوادوري على حشوة نيكاراغوية في معظمها. اسم إستيلي على سيجار مُلفوف في كوستاريكا دَينٌ للتبغ لا للورشة — تنصّ البطاقة على ذلك لأنّ قاعدة الأطلس هي مكان اللفّ.',
        '[{"name":"MBombay Classic","color":"#C9A96E","force":"Mild-Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"الخطّ الألطف — حشوة من نيكاراغوا وبيرو وجمهورية الدومينيكان."},{"name":"Gaaja","color":"#6B4226","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"تموز/يوليو 2016 — الفيل، gaja؛ قياس واحد في البداية، تورو مضغوط 6 × 54."},{"name":"M.Estelí","color":"#4A3728","force":"Medium-Full","wrapper":"هابانو 2000 إكوادوري","vitolas":[],"story":"2019 — الأقوى في الدار، حشوة نيكاراغوية في معظمها، قدم غير مقطوعة. تُلفّ في كوستاريكا رغم الاسم."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Vegas de Santiago : la troisieme marque de Puriscal, six langues ──
UPDATE `brands` SET `history` = CONCAT(`history`, '\n\n', 'Une troisième marque de cet atlas sort du même atelier : MBombay, la maison de Mel Shah, Bombay Tobak, y fait rouler toutes ses lignes depuis 2014. Puriscal roule donc pour Casdagli, Zechbauer et Bombay Tobak — et pour elle-même.') WHERE `name` = 'Vegas de Santiago' AND `history` NOT LIKE '%Bombay Tobak%';
UPDATE `brands` SET `history_en` = CONCAT(`history_en`, '\n\n', 'A third brand of this atlas comes out of the same workshop: MBombay, Mel Shah''s house, Bombay Tobak, has had all its lines rolled there since 2014. Puriscal thus rolls for Casdagli, Zechbauer and Bombay Tobak — and for itself.') WHERE `name` = 'Vegas de Santiago' AND `history_en` NOT LIKE '%Bombay Tobak%';
UPDATE `brands` SET `history_es` = CONCAT(`history_es`, '\n\n', 'Una tercera marca de este atlas sale del mismo taller: MBombay, la casa de Mel Shah, Bombay Tobak, hace liar allí todas sus líneas desde 2014. Puriscal lía pues para Casdagli, Zechbauer y Bombay Tobak — y para sí misma.') WHERE `name` = 'Vegas de Santiago' AND `history_es` NOT LIKE '%Bombay Tobak%';
UPDATE `brands` SET `history_de` = CONCAT(`history_de`, '\n\n', 'Eine dritte Marke dieses Atlas kommt aus derselben Werkstatt: MBombay, das Haus von Mel Shah, Bombay Tobak, lässt dort seit 2014 alle seine Linien rollen. Puriscal rollt also für Casdagli, Zechbauer und Bombay Tobak — und für sich selbst.') WHERE `name` = 'Vegas de Santiago' AND `history_de` NOT LIKE '%Bombay Tobak%';
UPDATE `brands` SET `history_zh` = CONCAT(`history_zh`, '\n\n', '本图集的第三个品牌出自同一作坊：梅尔·沙阿的公司 Bombay Tobak 旗下的 MBombay，自2014年起所有系列都在这里卷制。普里斯卡尔因此为 Casdagli、Zechbauer 与 Bombay Tobak 卷制——也为自己。') WHERE `name` = 'Vegas de Santiago' AND `history_zh` NOT LIKE '%Bombay Tobak%';
UPDATE `brands` SET `history_ar` = CONCAT(`history_ar`, '\n\n', 'علامةٌ ثالثة من هذا الأطلس تخرج من الورشة نفسها: MBombay، دار ميل شاه، Bombay Tobak، تُلفّ فيها كلّ خطوطها منذ 2014. فبوريسكال تلفّ إذن لِـCasdagli وZechbauer وBombay Tobak — ولنفسها.') WHERE `name` = 'Vegas de Santiago' AND `history_ar` NOT LIKE '%Bombay Tobak%';

