  (NULL,'migration 213','systeme','vegas_de_santiago_troisieme_marque','marque',0,
   'Paragraphe ajoute en six langues : MBombay (Bombay Tobak) est roulee a Puriscal depuis 2014, troisieme marque de l atlas sortie de cet atelier apres Villa Casdagli et Zechbauer');

SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Fable Cigars','Jake Wyatt Cigar Co.','Hiram & Solomon','Epic Cigars','Chogüí','Principle Cigars','Bombay Tobak')) = 7 AS sept_fiches,
  (SELECT `history` LIKE '%Bombay Tobak%' AND `history_ar` LIKE '%Bombay Tobak%' FROM `brands` WHERE `name` = 'Vegas de Santiago') AS puriscal_nomme,
  (SELECT `brands` LIKE '%Bombay Tobak%' FROM `producer_countries` WHERE `id` = 'costarica') AS costarica_annonce,
  (SELECT `brands` LIKE '%Jake Wyatt%' FROM `producer_countries` WHERE `id` = 'honduras') AS honduras_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 213') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
